[
  {
    "statement": "The most cost-effective methods with proven effectiveness to increase bat populations in agricultural landscapes include reducing pesticide, herbicide, and fertilizer use.",
    "citations": [
      "2013"
    ]
  },
  {
    "statement": "Implementing organic farming practices is a cost-effective method with proven effectiveness to increase bat populations in agricultural landscapes.",
    "citations": [
      "961"
    ]
  },
  {
    "statement": "Farms using few or no chemicals had higher overall bat activity than those using high chemical inputs.",
    "citations": [
      "2013"
    ]
  },
  {
    "statement": "One study in Germany recorded more bat species over grassland with moderate or no fertilizer applications than grassland with high fertilizer applications.",
    "citations": [
      "2013"
    ]
  },
  {
    "statement": "Farms or grasslands with few or no chemical inputs had higher overall bat activity than those using high chemical inputs.",
    "citations": [
      "2013"
    ]
  },
  {
    "statement": "Organic farming can be beneficial for bat populations.",
    "citations": [
      "961"
    ]
  },
  {
    "statement": "Four of nine studies found higher overall bat activity, bat feeding activity, and activity of various bat species on organic farms compared to non-organic farms.",
    "citations": [
      "961"
    ]
  },
  {
    "statement": "Two studies found higher activity of Myotis species over water and rivers on organic farms.",
    "citations": [
      "961"
    ]
  },
  {
    "statement": "One study found higher activity for two of three bat species over organic fields compared to conventionally managed fields.",
    "citations": [
      "961"
    ]
  },
  {
    "statement": "Providing bat boxes shows promise as a cost-effective intervention for bat populations.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "In 41 of 43 studies, bats used bat boxes in various habitats, including farmland and pasture.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Nine studies showed that bat box use increased by 2-10 times up to 10 years after installation.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Bat box occupancy rates varied widely.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Twenty-two studies found that less than half of the provided bat boxes were occupied.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Nine studies found that more than half of the provided bat boxes were occupied.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Agri-environment schemes showed mixed results for bat populations.",
    "citations": [
      "962"
    ]
  },
  {
    "statement": "Two of three studies in the UK found no significant difference in bat activity between farms under agri-environment schemes and conventional farms.",
    "citations": [
      "962"
    ]
  },
  {
    "statement": "One study found lower overall bat activity on farms participating in agri-environment schemes.",
    "citations": [
      "962"
    ]
  },
  {
    "statement": "Many potential interventions such as planting hedges, increasing semi-natural habitat, managing ditches, retaining forest fragments, and providing set-aside areas currently lack direct scientific evidence for their effectiveness on bat populations.",
    "citations": []
  }
]

[
  {
    "statement": "No studies have been found that evaluated the effects of releasing captive-bred bats into the wild.",
    "citations": [
      "2039"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of breeding bats in captivity to supplement wild populations affected by white-nose syndrome.",
    "citations": [
      "2009"
    ]
  },
  {
    "statement": "Studies have documented that captive breeding of bats can be successful.",
    "citations": [
      "2053"
    ]
  },
  {
    "statement": "Between 6% and 100% of female bats captured in the wild successfully conceive, give birth, and rear young in captivity.",
    "citations": [
      "2053"
    ]
  },
  {
    "statement": "Between 20% and 100% of bat pups born in captivity survive from 10 days to adulthood.",
    "citations": [
      "2053"
    ]
  },
  {
    "statement": "There is no documented evidence regarding the long-term success rates of reintroducing captive-bred bats back into wild populations.",
    "citations": []
  },
  {
    "statement": "Studies of other taxa show varying success rates for captive-bred reintroductions.",
    "citations": [
      "871",
      "2933"
    ]
  },
  {
    "statement": "One review found that 41% of release programmes of captive-bred or head-started amphibians showed evidence of breeding in the wild for multiple generations.",
    "citations": [
      "871"
    ]
  },
  {
    "statement": "Studies of captive-bred marine mammals found limited success with reintroduction.",
    "citations": [
      "2933"
    ]
  },
  {
    "statement": "Only 2 of 3 Antillean manatees survived for at least one year post-release.",
    "citations": [
      "2933"
    ]
  },
  {
    "statement": "Only 2 of 14 Florida manatees survived for at least one year post-release.",
    "citations": [
      "2933"
    ]
  }
]

[
  {
    "statement": "The available evidence for the effectiveness of public education campaigns for bat conservation across continents is extremely limited.",
    "citations": []
  },
  {
    "statement": "There is a significant research gap in the area of bat conservation education.",
    "citations": []
  },
  {
    "statement": "Most bat education actions have no evaluated studies.",
    "citations": []
  },
  {
    "statement": "There are no studies that have evaluated the effects of educating the public to improve the public's perception of bats.",
    "citations": [
      "1000"
    ]
  },
  {
    "statement": "There are no studies evaluating public information campaigns specifically about reducing cave disturbance to bats.",
    "citations": [
      "1003"
    ]
  },
  {
    "statement": "There are no studies on training conservationists and land managers on bat ecology to reduce roost disturbance.",
    "citations": [
      "997"
    ]
  },
  {
    "statement": "The only documented effectiveness evidence for bat conservation education comes from Africa, specifically Ghana.",
    "citations": []
  },
  {
    "statement": "In Ghana, two before-and-after studies found that educational interventions about bat hunting reduced hunters' intentions to hunt bats in the future.",
    "citations": [
      "1973",
      "1974"
    ]
  },
  {
    "statement": "One study in Ghana focused on the ecological roles of bats to discourage hunting.",
    "citations": [
      "1973"
    ]
  },
  {
    "statement": "Another study in Ghana focused on the disease risks from bat consumption to discourage hunting.",
    "citations": [
      "1974"
    ]
  },
  {
    "statement": "A review from North America suggests that education alone was not sufficient to change behavior.",
    "citations": [
      "162"
    ]
  },
  {
    "statement": "A review from North America suggests education was a necessary catalytic factor for economic incentives and law enforcement.",
    "citations": [
      "162"
    ]
  },
  {
    "statement": "No comparative studies examining the effectiveness of bat conservation education campaigns across different continents were identified.",
    "citations": []
  }
]

[
  {
    "statement": "Bat boxes appear to be the most studied and potentially cost-effective method for creating artificial bat roosts.",
    "citations": []
  },
  {
    "statement": "Forty-four studies evaluated providing bat boxes for roosting bats.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Forty-one of 43 studies found that bats used bat boxes installed in various habitats including forest, woodland, farmland, urban areas, and buildings.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "A review of 109 studies found that 72 bat species used bat boxes.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Eighteen species of bat commonly use bat boxes.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Thirty-one species of bat use bat boxes as maternity roosts.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Different materials used for bat boxes affect usage patterns.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Bats used black bat boxes more than grey, white or wooden boxes.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Bats used both resin and wood cylindrical bat boxes.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Resin bat boxes became occupied more quickly than wood boxes.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Concrete bat boxes had higher occupancy rates than wooden bat boxes.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "One study found that larger bat boxes had higher occupancy rates.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Eight of sixteen artificial hollows cut into trees were used by roosting long-eared bats in Australia.",
    "citations": [
      "2047"
    ]
  },
  {
    "statement": "Artificial caves or hibernacula were used by up to four bat species.",
    "citations": [
      "2049"
    ]
  },
  {
    "statement": "One study found increasing bat usage of artificial caves or hibernacula over nine years after construction.",
    "citations": [
      "2049"
    ]
  },
  {
    "statement": "Studies on managing microclimate in artificial roosts found mixed results with heated bat boxes.",
    "citations": [
      "2052"
    ]
  },
  {
    "statement": "Simple, non-heated designs for bat boxes may be more cost-effective.",
    "citations": [
      "2052"
    ]
  },
  {
    "statement": "Various artificial roost types can be successful.",
    "citations": []
  },
  {
    "statement": "Standard bat boxes appear to offer the best combination of proven effectiveness and likely cost-efficiency.",
    "citations": []
  },
  {
    "statement": "The effectiveness of standard bat boxes is based on extensive research showing the boxes' widespread use across multiple species and habitats.",
    "citations": []
  }
]
